package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
public class RootFamilyDiagnosticProfileTest {
 @Test public void oneFrameAuditRejectsBusinessAndSecondPhase(){assertTrue(RootFamilyDiagnosticProfile.ACTIVE);assertTrue(RootFamilyDiagnosticProfile.modeAllowed(RootCaptureScope.Mode.PREFLIGHT));assertFalse(RootFamilyDiagnosticProfile.modeAllowed(RootCaptureScope.Mode.BUSINESS));assertFalse(RootFamilyDiagnosticProfile.modeAllowed(null));assertTrue(RootFamilyDiagnosticProfile.phaseAllowed(RootCaptureScope.Mode.PREFLIGHT,RootCaptureScope.Phase.FIRST));assertFalse(RootFamilyDiagnosticProfile.phaseAllowed(RootCaptureScope.Mode.PREFLIGHT,RootCaptureScope.Phase.SECOND));assertFalse(RootFamilyDiagnosticProfile.phaseAllowed(RootCaptureScope.Mode.BUSINESS,RootCaptureScope.Phase.FIRST));}
 @Test public void independentAuditNamespaceAndNinetySecondIntent(){assertNotEquals(RootFamilyDiagnosticProfile.DIRECTORY,RootCaptureScope.PREFLIGHT_DIRECTORY);assertNotEquals(RootFamilyDiagnosticProfile.DIRECTORY,AutonomousRewardCardScope.DIRECTORY);assertEquals(91000,RootFamilyDiagnosticProfile.visibleDeadline(181000,1000));assertEquals(2000,RootFamilyDiagnosticProfile.visibleDeadline(2000,1000));long s=RootFamilyDiagnosticProfile.STARTS_UTC,e=RootFamilyDiagnosticProfile.EXPIRES_UTC;assertFalse(RootFamilyDiagnosticProfile.current(s-1));assertTrue(RootFamilyDiagnosticProfile.current(s));assertFalse(RootFamilyDiagnosticProfile.current(e));}
 @Test public void familyCaptureIsPureNativeObservationNotQuote(){var c=ReadOnlyTwoStageRun.Capture.moreFamilyDiagnostic(new Object(),"fixture-diagnostic",523,1000,0,1,()->false);var o=c.prepare(AutonomousCardFixture.pixels(false,false),523,1000,AutonomousCardFixture.rows(false,false),()->false);assertNotNull(o);assertTrue(o.validNativeShape());assertEquals(LiveRewardCardObservation.Status.OBSERVED,o.frame.status());assertEquals(2,o.frame.cards().size());assertFalse(o.quoteComplete());assertNull(c.prepare(AutonomousCardFixture.pixels(false,false),523,1000,AutonomousCardFixture.rows(false,false),()->false));}
 @Test public void revokedCaptureCannotYieldObservation(){var c=ReadOnlyTwoStageRun.Capture.moreFamilyDiagnostic(new Object(),"fixture-revoked",523,1000,0,1,()->true);assertNull(c.prepare(AutonomousCardFixture.pixels(false,false),523,1000,AutonomousCardFixture.rows(false,false),()->false));}
 @Test public void diagnosticWindowIsIndependentOfHistoricalBusinessWindow(){long s=RootFamilyDiagnosticProfile.STARTS_UTC,e=RootFamilyDiagnosticProfile.EXPIRES_UTC;assertTrue(RootFamilyDiagnosticProfile.current(RootCaptureScope.EXPIRES_UTC));assertFalse(RootCaptureScope.current(RootCaptureScope.EXPIRES_UTC));assertEquals(91000,RootFamilyDiagnosticProfile.sessionDeadline(1000,s));assertEquals(91000,RootFamilyDiagnosticProfile.deadline(1000,s,200000));assertFalse(RootFamilyDiagnosticProfile.admissionCurrent(e-90000));assertThrows(SecurityException.class,()->RootFamilyDiagnosticProfile.sessionDeadline(1000,e-90000));assertThrows(SecurityException.class,()->RootFamilyDiagnosticProfile.deadline(1000,s,1000));assertNotEquals(RootFamilyDiagnosticProfile.V26_DIRECTORY,RootFamilyDiagnosticProfile.DIRECTORY);}
 private static String source(String n)throws Exception{Path p=Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n);if(!Files.exists(p))p=Path.of(System.getProperty("working.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n);if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once",n);return Files.readString(p);}
 @Test public void optionalDiagnosticGateRemainsBeforeConstruction()throws Exception{String a=source("DormantCaptureConfirmationActivity.java");int start=a.indexOf("private void confirmRoot(RootCaptureScope.Mode mode)");assertTrue(start>=0);assertTrue(a.indexOf("RootFamilyDiagnosticProfile.modeAllowed(mode)",start)<a.indexOf("NativeAutonomousCardRun.confirmed(this)",start));String r=source("CaptureSessionRuntime.java");int s=r.indexOf("static CaptureSessionRuntime startRoot");assertTrue(r.indexOf("RootFamilyDiagnosticProfile.phaseAllowed",s)<r.indexOf("business.reserve",s));assertTrue(r.contains("if(returnReadIntent!=null||boundedIntent!=null||seriesIntent!=null||RootFamilyDiagnosticProfile.ACTIVE)return null; // Historical scalar display only"));}
 @Test public void newStoreAndFixedFamilyTemplateWired()throws Exception{String r=source("CaptureSessionRuntime.java");assertTrue(r.contains("RootCaptureScope.diagnosticStore(activity.getNoBackupFilesDir().toPath())"));assertTrue(r.contains("ReadOnlyTwoStageRun.Capture.moreFamilyDiagnostic"));assertTrue(source("RootCaptureScope.java").contains("Phase.FIRST,RootFamilyDiagnosticProfile.DIRECTORY"));assertTrue(source("VisibleCaptureAuthority.java").contains("Diagnostic-only live issuer"));String ui=source("RootCaptureUi.java");assertTrue(ui.indexOf("if(RootFamilyDiagnosticProfile.ACTIVE)")<ui.indexOf("Runnable preflight,Runnable business,Runnable cancel)")+150);assertTrue(ui.contains("只读同帧图像审计：1帧，零输入"));}
}
